<html lang="pt-BR">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="color-scheme" content="light">
    <title>@yield('title', 'Plataforma Mix7')</title>
    <style>
        :root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:#202e35;background:#f5f6f5;font-synthesis:none;text-rendering:optimizeLegibility}*{box-sizing:border-box}body{margin:0;min-height:100vh}.shell{min-height:100vh;display:grid;grid-template-columns:252px minmax(0,1fr)}.sidebar{background:linear-gradient(165deg,#202e35 0%,#204b61 78%,#27647b 100%);color:white;padding:28px 18px;display:flex;flex-direction:column;gap:34px}.brand{display:flex;align-items:center;gap:12px;padding:0 10px;font-size:18px;font-weight:750;letter-spacing:.01em}.brand-mark{height:38px;width:38px;border-radius:13px;background:#8ecde2;color:#173b4b;display:grid;place-items:center;font-size:18px;font-weight:850}.nav-label{padding:0 12px;color:#bed4dc;text-transform:uppercase;letter-spacing:.12em;font-size:11px;font-weight:750}.nav-item{display:flex;align-items:center;gap:12px;margin-top:8px;padding:12px;border-radius:12px;color:#e9f2f4;text-decoration:none;font-size:14px}.nav-item.active,.nav-item:hover{background:#ffffff1a;color:#fff}.nav-state{margin-left:auto;color:#bed4dc;font-size:10px;font-weight:600}.sidebar-note{margin-top:auto;padding:15px;border:1px solid #ffffff27;border-radius:14px;color:#d7e7eb;font-size:12px;line-height:1.6}.main{min-width:0}.topbar{height:76px;background:#fff;border-bottom:1px solid #e7eceb;display:flex;align-items:center;justify-content:flex-end;padding:0 36px;gap:14px}.user-chip{display:flex;align-items:center;gap:10px;color:#52666e;font-size:13px}.avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#e3f3f8;color:#204b61;font-weight:750}.logout{border:1px solid #dce5e6;background:white;color:#38515b;border-radius:10px;padding:9px 13px;font:inherit;font-size:13px;cursor:pointer}.content{max-width:1320px;margin:auto;padding:38px 40px}.eyebrow{color:#52869a;text-transform:uppercase;letter-spacing:.12em;font-weight:750;font-size:11px;margin:0 0 10px}.heading{margin:0;font-size:32px;letter-spacing:-.035em;color:#202e35}.subheading{color:#64777d;margin:10px 0 0;line-height:1.6}.welcome{padding:26px 28px;border:1px solid #deeaeb;border-radius:22px;background:linear-gradient(115deg,#fff 0%,#f3fbfd 100%);display:flex;align-items:center;justify-content:space-between;gap:24px}.status{padding:8px 11px;border-radius:999px;background:#e3f5ed;color:#267050;font-size:12px;font-weight:700;white-space:nowrap}.section-title{font-size:16px;margin:30px 0 14px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.module{background:#fff;border:1px solid #e3e9e8;border-radius:18px;padding:20px;min-height:154px}.module .icon{width:38px;height:38px;border-radius:12px;background:#eaf6fa;color:#39758b;display:grid;place-items:center;font-size:17px}.module h3{font-size:15px;margin:15px 0 6px}.module p{color:#718087;font-size:13px;line-height:1.55;margin:0}.module.pending{background:#fcfdfd;border-style:dashed}.footnote{font-size:12px;color:#7c8a8e;margin-top:22px}.login-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(ellipse at 15% 10%,#e2f5fa 0%,#f5f6f5 52%)}.login-card{width:min(100%,440px);background:#fff;border:1px solid #e3ebea;border-radius:24px;padding:34px;box-shadow:0 18px 65px #204b6114}.login-title{font-size:26px;letter-spacing:-.03em;margin:28px 0 8px}.field{display:block;margin-top:19px;color:#3d555e;font-size:13px;font-weight:650}.field input{display:block;width:100%;margin-top:8px;border:1px solid #d6e0e1;border-radius:11px;padding:12px 13px;font:inherit;font-size:15px;color:#202e35}.field input:focus{outline:3px solid #8ecde244;border-color:#52869a}.primary{margin-top:23px;width:100%;min-height:46px;background:#204b61;color:white;border:0;border-radius:11px;font:inherit;font-size:14px;font-weight:750;cursor:pointer}.error{font-size:12px;color:#a73737;margin-top:6px}.security-note{margin-top:22px;font-size:12px;line-height:1.55;color:#738187}.login-brand{padding:0}.mobile-nav{display:none}@me